	"Reported user: {reportedName}": "Utilisateur signalé : {reportedName}",
	"There are no common battles between '{escapedTarget}' and '{escapedCreator}'.": "Il n'y a aucun combat en commun entre « {escapedTarget} » et « {escapedCreator} ».",
	"Showing {battleCount} common battle(s) between '{escapedTarget}' and '{escapedCreator}': ": "Affichage de {battleCount} combat(s) en commun entre « {escapedTarget} » et « {escapedCreator} » : ",
	"{user.name} opened a new ticket. Issue: {ticketTypeName}": "{user.name} a ouvert un nouveau ticket. Problème : {ticketTypeName}",
