	"That ticket cannot be resolved with /helpticket resolve. Join it instead.": "Ce ticket ne peut pas être résolu avec /helpticket resolve. Rejoignez-le plutôt.",
	"You resolved {ticketId}'s ticket.": "Vous avez résolu le ticket de {ticketId}.",
